/**
 * Risk classification for observed actions. Every entry here answers one
 * question: would a user lose something they cannot get back, or pay for
 * something they did not ask for? Those actions need a recorded authorization.
 * Everything else is only classified so the ledger can describe it.
 */

export const DEFAULT_PROTECTED_PREFIXES = [
  '.auto-dev/', '.autodev/', '.dsh/', '.codex/', '.github/workflows/',
  '.git/config', '.git/hooks/',
]


const TEMP_PREFIXES = ['/tmp/', '/var/tmp/', '/private/tmp/', '/private/var/tmp/']

/**
 * Directories whose contents are regenerated by the toolchain. Deleting them is
 * how the ecosystem works (`rm -rf node_modules` is a repair step, not a loss),
 * and refusing it would make the hard gate unusable on ordinary days.
 */
const REBUILDABLE_SEGMENTS = ['node_modules', 'dist', 'build', 'out', 'target', 'coverage', '.next', '.cache', '.turbo', '.venv', '__pycache__']

/**
 * Drop quoted spans before looking for shell verbs. `git commit -m "rm -rf tmp"`
 * is a message, not a delete — a gate that cannot tell the difference gets
 * switched off, which is worse than not having it.
 */
// Quoted spans become blanks so a mention of a path is not a write to it. Newlines
// stay: they separate statements, and collapsing them into spaces turned
// `rm -rf /tmp/a` followed by `mkdir -p /tmp/a` into one `rm` whose argument list
// contained "mkdir" — a scratch delete graded irreversible because of the next line.
const unquoted = command => command
  .replace(/"(?:[^"\\]|\\.)*"/g, ' ')
  .replace(/'(?:[^'\\]|\\.)*'/g, ' ')
  .replace(/[ \t]+/g, ' ')

/**
 * Drop heredoc bodies. `python3 - <<'PY' … PRODUCTION … write_text(…) … PY`
 * feeds a script to an interpreter; the words inside it are data being written,
 * not shell about to run, so grading the whole block as a production write made
 * every self-repair of this very file look like a deploy.
 */
const shellText = command => String(command).replace(
  /<<-?\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\1[\s\S]*?\n\s*\2\s*(?=\n|$)/g,
  ' ',
)

const isTempPath = path => {
  const clean = path.replace(/^['"]|['"]$/g, '').replace(/^~\//, `${process.env.HOME ?? '~'}/`)
  if (TEMP_PREFIXES.some(prefix => clean.startsWith(prefix))) return true
  return clean === '/tmp' || clean === '/var/tmp' || clean === '/private/tmp'
}

/**
 * Every path this command hands to `rm`, or null when it does not delete.
 *
 * Only the `rm` segments matter: reading the whole line as one argument list
 * made `rm -rf /tmp/x && mkdir -p /tmp/x` look like it deleted `&&` and `mkdir`
 * too, so scratch work got graded irreversible and people learned to answer
 * "yes, delete anything" without reading.
 */
function rmTargets(command) {
  const segments = command.split(/&&|\|\||;|\n|\|/).map(segment => segment.trim()).filter(Boolean)
  const targets = []
  let deleting = false
  for (const segment of segments) {
    const words = segment.split(/\s+/).filter(Boolean)
    const index = words.findIndex(word => word === 'rm' || word.endsWith('/rm'))
    if (index < 0) continue
    deleting = true
    for (const word of words.slice(index + 1)) {
      if (word.startsWith('-') || /^[A-Z_][A-Z0-9_]*=/.test(word)) continue
      // A redirection or a trailing comment is not a path being deleted.
      // `rm -rf /tmp/a /tmp/b 2>/dev/null` graded irreversible because
      // `2>/dev/null` read as a target, which is precisely the kind of noise
      // that teaches people to approve without reading.
      if (/^\d*>>?/.test(word) || /^&>/.test(word) || word.startsWith('#')) break
      targets.push(word)
    }
  }
  return deleting ? targets : null
}

/** True when every path handed to `rm` is toolchain output that a rebuild recreates. */
function onlyRebuildableTargets(command) {
  const targets = rmTargets(command)
  if (!targets || !targets.length) return false
  return targets.every(target => {
    const clean = target.replace(/^['"]|['"]$/g, '')
    const segments = clean.split('/').filter(Boolean)
    return segments.some(segment => REBUILDABLE_SEGMENTS.includes(segment))
  })
}

/** True when every path handed to `rm` sits under an OS temp directory. */
function onlyTempTargets(command) {
  const targets = rmTargets(command)
  if (!targets || !targets.length) return false
  return targets.every(isTempPath)
}

const DESTRUCTIVE = [
  // A recursive delete of nothing but OS temp paths is scratch work, not a
  // destructive act on the user's project — grading it irreversible would train
  // people to answer "yes, delete anything" without reading.
  {
    id: 'recursive-delete',
    test: command => /(^|[\s;&|])rm\s+(-[a-zA-Z]*[rf][a-zA-Z]*\s+)+/.test(command)
      && !onlyTempTargets(command)
      && !onlyRebuildableTargets(command),
  },
  { id: 'forced-git-reset', test: command => /git\s+(reset\s+--hard|clean\s+-[a-zA-Z]*f|push\s+(--force|-f)\b|branch\s+-D\b|stash\s+(drop|clear)\b)/.test(command) },
  { id: 'history-rewrite', test: command => /git\s+(rebase|filter-branch|commit\s+--amend)/.test(command) },
  { id: 'sql-destruction', payload: true, test: command => /\b(DROP\s+(TABLE|DATABASE|SCHEMA)|TRUNCATE\s+TABLE|DELETE\s+FROM\s+\w+\s*(;|$))/i.test(command) },
  { id: 'infrastructure', test: command => /\b(kubectl\s+(apply|delete|scale)|terraform\s+(apply|destroy)|helm\s+(install|upgrade|uninstall))\b/.test(command) },
  { id: 'disk-or-package', test: command => /\b(mkfs|dd\s+if=|npm\s+publish|pnpm\s+publish|yarn\s+publish|cargo\s+publish)\b/.test(command) },
]

const PRODUCTION = [
  { id: 'deploy', test: command => /\b(deploy|vercel\s+--prod|fly\s+deploy|gcloud\s+app\s+deploy|aws\s+deploy|serverless\s+deploy|gh\s+release\s+create)\b/i.test(command) },
  { id: 'production-write', payload: true, test: command => /\b(prod|production)\b/i.test(command) && /\b(write|insert|update|delete|migrate|seed|flush)\b/i.test(command) },
  { id: 'remote-shell', test: command => /^\s*ssh\s+\S+/.test(command) },
]

/**
 * Structural rules read the shell as the shell sees it (quoted words are data).
 * Payload rules (`psql -c "delete from prod.users"`) read the quotes, because the
 * dangerous text lives inside them — the two need different views of one line.
 */
function matches(rules, views) {
  return rules.filter(rule => rule.test(rule.payload ? views.payload : views.code)).map(rule => rule.id)
}

export function classifyCommand(command) {
  if (typeof command !== 'string' || command.trim() === '') return { mutating: false, destructive: [], production: [] }
  const script = shellText(command)
  const views = { code: unquoted(script), payload: script }
  const code = views.code
  const destructive = matches(DESTRUCTIVE, views)
  const production = matches(PRODUCTION, views)
  const mutating = destructive.length > 0 || production.length > 0 || [
    /(^|[^0-9&>])>{1,2}\s*\S/, /\b(tee|sed\s+-i|perl\s+-i|truncate)\b/,
    /\b(mv|cp|rm|mkdir|touch|chmod|chown|ln)\b/,
    /git\s+(add|commit|checkout|restore|apply|merge|rebase|stash)\b/,
    /\b(npm|pnpm|yarn|bun)\s+(install|add|remove|uninstall|run)\b/,
    /\b(pip|poetry|uv)\s+(install|add|remove)\b/,
    /\b(make|cmake|gradle|mvn|go\s+build|go\s+mod|cargo\s+(build|add|install))\b/,
  ].some(pattern => pattern.test(code))
  return { mutating, destructive, production }
}

/** Which paths a write touches, relative to the project root. */
const FILE_WRITE_TOOLS = new Set(['write', 'write_file', 'edit', 'edit_file', 'str_replace_editor'])

/**
 * Risk of the call that is running right now, read from its own arguments.
 *
 * The post-execute hook fires before the log carries the call, and a window that
 * still holds an hour-old command would keep re-asking for the same permission.
 * Both problems disappear if the notice is about the action itself: this returns
 * what that call would cost, here and now.
 */
export function risksOfCall(call, { protectedPrefixes = DEFAULT_PROTECTED_PREFIXES } = {}) {
  const destructive = new Set()
  const production = new Set()
  const args = call && typeof call.arguments === 'object' && call.arguments ? call.arguments : {}
  const command = typeof args.command === 'string' ? args.command : ''
  if (command) {
    const classified = classifyCommand(command)
    for (const risk of classified.destructive) destructive.add(risk)
    for (const risk of classified.production) production.add(risk)
  }
  const path = typeof args.path === 'string' ? args.path
    : typeof args.file_path === 'string' ? args.file_path
      : ''
  if (path && FILE_WRITE_TOOLS.has(String(call.name ?? '')) && isProtectedPath(normalizePath(path), protectedPrefixes)) {
    destructive.add('control-plane')
  }
  // The same protection has to survive being expressed as a shell redirect: a
  // gate that guards the file tool and not the shell is a gate with a door.
  if (command && shellWritePaths(command).some(target => isProtectedPath(normalizePath(target), protectedPrefixes))) {
    destructive.add('control-plane')
  }
  return { destructive: [...destructive], production: [...production] }
}

/**
 * Paths a shell command writes to, as far as its text can prove.
 *
 * `echo '{}' > .auto-dev/ledger.json` edits the control plane without ever calling
 * a file tool, so a gate that only inspects `write`/`edit` arguments is bypassed by
 * a redirect. This is deliberately a small grammar — redirections, `tee`, `sed -i`,
 * `cp`/`mv`/`ln` destinations — because guessing more would mean refusing commands
 * people wrote to do something else. Interpreter writes (`node -e`,
 * `python3 - <<EOF`) stay out of reach of text analysis and are listed as a known
 * limit instead.
 */
export function shellWritePaths(command) {
  return shellWritePathsAt(command, 0)
}

/**
 * Split a command line into simple commands without being fooled by quoting.
 *
 * The previous version split on `;`, `|` and `&&` first and then looked for `>`:
 * `node -e "console.log('echo x > .auto-dev/y')"` became two segments, the second
 * of which *looked* like a redirect into the control plane, and a probe was refused
 * as an irreversible write to a file it only mentioned. Quoting decides what is code
 * and what is data, so it is tracked while splitting, not afterwards.
 */
function splitSegments(text) {
  const segments = []
  let current = ''
  let state = null
  let escape = false
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index]
    if (escape) { current += character; escape = false; continue }
    if (character === '\\' && state !== "'") { current += character; escape = true; continue }
    if (state) {
      current += character
      if (character === state) state = null
      continue
    }
    if (character === "'" || character === '"') { state = character; current += character; continue }
    const pair = text.slice(index, index + 2)
    if (pair === '&&' || pair === '||' || pair === '>>' && false) {
      segments.push(current); current = ''; index += 1; continue
    }
    if (character === ';' || character === '|' || character === '\n') {
      segments.push(current); current = ''; continue
    }
    current += character
  }
  segments.push(current)
  return segments.map(segment => segment.trim()).filter(Boolean)
}

/** Redirect targets mentioned outside quotes, with the target's own quoting removed. */
function redirectTargets(segment) {
  const targets = []
  let state = null
  let escape = false
  for (let index = 0; index < segment.length; index += 1) {
    const character = segment[index]
    if (escape) { escape = false; continue }
    if (character === '\\' && state !== "'") { escape = true; continue }
    if (state) { if (character === state) state = null; continue }
    if (character === "'" || character === '"') { state = character; continue }
    if (character !== '>') continue
    let cursor = index + 1
    while (segment[cursor] === ' ') cursor += 1
    let word = ''
    let quote = null
    while (cursor < segment.length) {
      const next = segment[cursor]
      if (quote) { if (next === quote) quote = null; else word += next; cursor += 1; continue }
      if (next === "'" || next === '"') { quote = next; cursor += 1; continue }
      if (/[\s;&|>]/.test(next)) break
      word += next
      cursor += 1
    }
    if (word && word !== '/dev/null' && !word.startsWith('&')) targets.push(word)
    index = cursor - 1
  }
  return targets
}

function shellWritePathsAt(command, depth) {
  if (typeof command !== 'string' || !command || depth > 3) return []
  const targets = []
  const heredocBodies = []
  // A heredoc body is data handed to a program, not shell code: a document that
  // explains `echo '{}' > .auto-dev/ledger.json` must not be refused as that write.
  const code = []
  let closing = null
  for (const line of command.split('\n')) {
    if (closing) {
      if (line.trim() === closing) closing = null
      continue
    }
    const opener = /<<-?\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\1/.exec(line)
    if (opener) closing = opener[2]
    code.push(line)
  }
  for (const segment of splitSegments(code.join('\n'))) {
    const heredoc = /<<-?\s*['"]?([A-Za-z_][A-Za-z0-9_]*)['"]?/.exec(segment)
    if (heredoc) heredocBodies.push(heredoc[1])
    targets.push(...redirectTargets(segment))
    const words = wordsOf(segment)
    const program = words[0]?.replace(/^.*\//, '')
    // `sh -c "..."` and `eval "..."` run their argument as code: skipping them would
    // make the whole check a formality anyone can step around with one wrapper.
    if (['sh', 'bash', 'zsh', 'dash', 'eval'].includes(program)) {
      const codeIndex = words.indexOf('-c')
      const inner = program === 'eval' ? words.slice(1).join(' ') : words.slice(codeIndex + 1).join(' ')
      if (inner) targets.push(...shellWritePathsAt(inner, depth + 1))
    }
    if (program === 'tee') targets.push(...words.slice(1).filter(word => !word.startsWith('-')))
    if (program === 'sed') {
      const inPlace = words.some(word => /^-[a-zA-Z]*i/.test(word))
      if (inPlace) {
        const scriptIndex = words.findIndex(word => /^-[a-zA-Z]*i/.test(word)) + 1
        targets.push(...words.slice(scriptIndex + 1).filter(word => !word.startsWith('-')))
      }
    }
    if (program === 'cp' || program === 'mv' || program === 'ln' || program === 'install' || program === 'rsync') {
      const operands = words.slice(1).filter(word => !word.startsWith('-'))
      if (operands.length >= 2) targets.push(operands[operands.length - 1])
    }
  }
  return [...new Set(targets.filter(target => target && !heredocBodies.includes(target)))]
}

/**
 * Words of one simple command, with quoting removed and quoted runs kept whole —
 * `> "out file.txt"` names one file, not two.
 */
function wordsOf(segment) {
  return (segment.match(/"(?:[^"\\]|\\.)*"|'(?:[^']*)'|\S+/g) ?? [])
    .map(word => word.replace(/^['"]|['"]$/g, ''))
}

export function writtenPaths(row) {
  const paths = []
  if (Array.isArray(row.paths)) paths.push(...row.paths)
  if (typeof row.path === 'string') paths.push(row.path)
  if (typeof row.name === 'string' && /^(write|edit|multi_edit|apply_patch|create_file|str_replace|notebook_edit)$/.test(row.name)) {
    const value = row.value
    if (value && typeof value === 'object') {
      if (typeof value.path === 'string') paths.push(value.path)
      if (typeof value.file_path === 'string') paths.push(value.file_path)
    }
  }
  return [...new Set(paths.filter(path => typeof path === 'string' && path !== ''))]
}

/**
 * A protected path is protected wherever it sits: the tools report absolute
 * paths (`/repo/.auto-dev/ledger.json`) while the setting is written the way a
 * person says it (` .auto-dev/ `), and comparing the two literally never
 * matches. Containment is decided at a segment boundary so `not.auto-dev/`
 * does not sneak in.
 */
export function isProtectedPath(path, prefixes = DEFAULT_PROTECTED_PREFIXES) {
  const normalized = normalizePath(path)
  return prefixes.some(raw => {
    const prefix = normalizePath(raw).replace(/\/+$/, '')
    if (!prefix) return false
    return normalized === prefix || normalized.startsWith(`${prefix}/`) || normalized.includes(`/${prefix}/`) || normalized.endsWith(`/${prefix}`)
  })
}

export function normalizePath(path) {
  return String(path).replace(/\\/g, '/').replace(/^\.\//, '')
}

/** Scope entries are project-relative prefixes; `.` or an empty scope means everything. */
export function inScope(path, scope) {
  const normalized = normalizePath(path)
  const entries = (scope ?? []).map(normalizePath).filter(entry => entry !== '' && entry !== '.')
  if (!entries.length) return true
  return entries.some(entry => normalized === entry || normalized.startsWith(`${entry}/`))
}

export function scopeViolations(paths, scope) {
  return paths.filter(path => !inScope(path, scope))
}

/**
 * Commands whose whole purpose is to produce an observable verdict. Used only
 * to keep the "you never checked" reminder honest: a call that writes a file
 * and then runs a check in the same shell line did check its own work.
 */
const CHECK_PATTERNS = [
  /\b(node|deno|bun)\s+(--test|--check|-e\s+['"]?assert)\b/,
  /\b(npm|pnpm|yarn|bun)\b[^&|;]*\b(run\s+)?(test|build|lint|typecheck|check|verify|ci)\b/,
  /\b(npx|pnpm\s+dlx)\b[^&|;]*\b(vitest|jest|tsc|mocha|playwright|cypress|eslint|biome)\b/,
  /\b(vitest|jest|mocha|playwright|cypress|tsc|eslint|biome|ruff|mypy|pyright|flake8|phpstan|rubocop)\b/,
  /\b(pytest|python\s+-m\s+(pytest|unittest)|tox)\b/,
  /\b(go|cargo|dotnet|swift|sbt)\s+(test|build|vet|clippy|check)\b/,
  /\b(mvn|gradle|gradlew|make|cmake|ninja|bazel|buck)\b/,
  /\b(make|just|cargo|poetry|uv|rake|mix|elixir)\b[^&|;]*\b(test|check|build|verify)\b/,
  /\b(curl|wget|http|httpie|grpcurl)\b/,
  /\b(git\s+diff\s+--stat|git\s+status)\b/,
]

/**
 * @param {string|undefined} command a shell command line
 * @returns {boolean} whether the line runs something that reports a verdict
 */
export function isCheckCommand(command) {
  if (typeof command !== 'string' || command === '') return false
  return CHECK_PATTERNS.some(pattern => pattern.test(command))
}
